-- Apply once to an existing Form No. 6 database to enable leave credit tracking.
USE leave_monitor;
CREATE TABLE leave_balances(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,category VARCHAR(100) NOT NULL,allocated_days DECIMAL(8,2) NOT NULL DEFAULT 0,used_days DECIMAL(8,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE KEY uq_leave_balance_user_category(school_id,user_id,category),INDEX idx_leave_balance_user(school_id,user_id)) ENGINE=InnoDB;
CREATE TABLE leave_credit_ledger(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,school_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,leave_request_id BIGINT UNSIGNED NULL,category VARCHAR(100) NOT NULL,entry_type ENUM('allocation','adjustment','deduction','restoration') NOT NULL,days_change DECIMAL(8,2) NOT NULL,balance_after DECIMAL(8,2) NOT NULL,description VARCHAR(500) NOT NULL,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(school_id) REFERENCES schools(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(leave_request_id) REFERENCES leave_requests(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,UNIQUE KEY uq_ledger_request_type(leave_request_id,entry_type),INDEX idx_ledger_employee(school_id,user_id,created_at)) ENGINE=InnoDB;
